  7312  static int make_parent_dir(const char *path)
  7313  {
  7314          char *cp, errmsg[STRERR_BUFSIZE];
  7315          char *dname, *dir;
  7316          int err = 0;
  7317
  7318          dname = strdup(path);
  7319          if (dname == NULL)
  7320                  return -ENOMEM;
